#define MAXN 1005
#define MAXM 20005
struct Edge { int to, next; } e[MAXM];
int head[MAXN], cnt;
int dist[MAXN], que[MAXN];
void addEdge(int u, int v) {          /* 头插法插入一条边 */
    e[++cnt].to = v;
    e[cnt].next = head[u];
    head[u] = cnt;
}
/* TODO: 读入边之前必须先把 head[1..n] 全部初始化为 -1（如 memset(head, -1, sizeof(head))）；
   每条无向边需调用 addEdge(u, v) 和 addEdge(v, u) 各一次 */

/* 输入示例 */
4 3
1 2
2 3
3 4
/* 输出示例 */
0 1 2 3

analysis:
解题思路：在无权图中，广度优先搜索按“距源点的边数”分层扩展，因此顶点第一次被访问时所经过的边数就是它的最短边数。用数组 dist 记录距离，初始时全部置为 -1（既表示未访问，也表示不可达），把源点 1 的 dist[1] 置为 0 并入队。之后不断取出队头顶点 u，遍历其邻接表中所有邻接点 v：若 dist[v] 仍为 -1，说明 v 第一次被发现，令 dist[v] = dist[u] + 1 并将 v 入队；若已访问则跳过。搜索结束后，dist 数组中即为各顶点到顶点 1 的最短边数，仍为 -1 的即为不可达顶点。关键代码片段：
void bfs(int s, int n) {
    int front = 0, rear = 0;
    for (int i = 1; i <= n; i++) dist[i] = -1;
    dist[s] = 0;
    que[rear++] = s;
    while (front < rear) {
        int u = que[front++];
        for (int k = head[u]; k != -1; k = e[k].next) {
            int v = e[k].to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                que[rear++] = v;
            }
        }
    }
}
时间复杂度：每个顶点入队出队一次，每条边在两个顶点的邻接表中各被扫描一次，故为 O(n + m)。空间复杂度：邻接表 O(n + m)，dist 数组与队列各 O(n)。易错点：用数组模拟队列时忘记在出队后判断边界；对重边和自环不做处理时也无妨，因为 dist 的判重会自然过滤，但需保证数组容量足够（本题开 2m）。

code_context:
int binarySearch(int a[], int n, int key);

/* 输入示例 */
8 11
1 3 5 7 9 11 13 15
/* 输出示例 */
5

analysis:
解题思路：二分查找适用于顺序存储且按关键字有序的表。用两个下标 low 和 high 表示当前可能的查找区间（初始为 0 和 n-1），循环条件是 low <= high。每轮取中点 mid = low + (high - low) / 2，把 a[mid] 与 key 比较：若相等则查找成功，返回 mid；若 a[mid] < key，说明目标只可能在右半区，令 low = mid + 1；若 a[mid] > key，说明目标只可能在左半区，令 high = mid - 1。当 low > high 时区间为空，说明查找失败，返回 -1。关键代码片段：
int binarySearch(int a[], int n, int key) {
    int low = 0, high = n - 1, mid;
    while (low <= high) {
        mid = low + (high - low) / 2;
        if (a[mid] == key) return mid;
        else if (a[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}
时间复杂度：每轮比较把查找区间缩小约一半，最多比较 ⌈log2(n+1)⌉ 次，故为 O(log n)。空间复杂度：只用 low、high、mid 三个整型变量，为 O(1)。易错点：一是把循环条件写成 low < high 会导致漏查只剩一个元素的区间；二是用 (low + high) / 2 计算中点，当 n 很大时 low + high 可能超出 int 范围，写成 low + (high - low) / 2 更稳妥；三是更新区间时忘记 ±1 会造成死循环。本题示例中下标 5 处的元素为 11，返回 5。

